"OLAYLAR_ORTACAG_ORTADOGU:1291-07-01:0":{"b": ["Sidon yapita kwa Mamluk (wapiganaji wa Templier wajiondoa)", "2339a488"], "d": ["Kwa kutekwa kwa Akka (690/1291), wapiganaji wa Templier walioondoka huko walikimbilia Sidon; mji ulipita mikononi mwa Mamluk Receb 690 / Julai 1291 na kuta zake zikabomolewa.", "4c9103e0"]},
